/* Generated by engine/build-site.mjs — no dependencies, no network.
   The episode list is ALREADY in the HTML. This only hides, reorders and annotates it, so the
   archive still works with JavaScript off. */
(function () {
  "use strict";
  var EPS = window.__EPISODES__ || [];
  var q = document.getElementById("q");
  var list = document.getElementById("eps");
  if (!q || !list) return;

  var clear = document.getElementById("qclear");
  var count = document.getElementById("count");
  var empty = document.getElementById("empty");
  var more = document.getElementById("more");
  var filters = document.getElementById("filters");
  var PAGE = 24;               // cards shown before "show more" — keeps first paint cheap at scale
  var shown = PAGE, cat = "", terms = [];

  var byslug = {};
  EPS.forEach(function (e) { byslug[e.s] = e; });
  var nodes = [].slice.call(list.children);

  if (filters) filters.hidden = false;
  count.hidden = false;

  function norm(s) { return (s || "").toLowerCase(); }
  function esc(s) { return s.replace(/[&<>]/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c]; }); }

  /* Highlight every term in a plain string. Escaped first, so a claim containing < is safe. */
  function hi(text) {
    var out = esc(text);
    terms.forEach(function (t) {
      out = out.replace(new RegExp("(" + t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + ")", "ig"), "<mark>$1</mark>");
    });
    return out;
  }

  /* Every term must appear somewhere in the episode — AND, not OR. With hundreds of episodes an
     OR search returns the whole archive for any two-word query, which is the same as no search. */
  function match(e) {
    if (cat && e.c !== cat) return null;
    if (!terms.length) return { hits: [] };

    var meta = norm([e.t, e.b, e.q, e.c, e.g.join(" "), e.p.join(" ")].join(" "));
    var hits = [];
    var covered = terms.map(function (t) { return meta.indexOf(t) > -1; });

    e.d.forEach(function (d) {
      var stem = d[0], dtitle = d[1], heads = d[2], claims = d[3];
      heads.forEach(function (h) {
        var text = norm(h[1]);
        terms.forEach(function (t, i) { if (text.indexOf(t) > -1) covered[i] = true; });
        if (terms.some(function (t) { return text.indexOf(t) > -1; }))
          hits.push({ where: dtitle, text: h[1], href: e.s + "/" + stem + ".html#" + h[0] });
      });
      claims.forEach(function (c) {
        var text = norm(c);
        terms.forEach(function (t, i) { if (text.indexOf(t) > -1) covered[i] = true; });
        if (terms.some(function (t) { return text.indexOf(t) > -1; }))
          hits.push({ where: dtitle, text: c, href: e.s + "/" + stem + ".html" });
      });
    });

    if (covered.indexOf(false) > -1) return null;
    return { hits: hits.slice(0, 4) };
  }

  function apply() {
    var visible = 0, total = 0;
    nodes.forEach(function (node) {
      var e = byslug[node.getAttribute("data-slug")];
      var m = e ? match(e) : null;
      var box = node.querySelector(".hits");
      if (!m) { node.hidden = true; if (box) { box.hidden = true; box.innerHTML = ""; } return; }
      total++;
      if (total > shown) { node.hidden = true; return; }
      node.hidden = false;
      visible++;
      if (box) {
        if (m.hits.length) {
          box.innerHTML = m.hits.map(function (h) {
            return '<li><a href="' + h.href + '"><span class="where">' + esc(h.where) + "</span>" + hi(h.text) + "</a></li>";
          }).join("");
          box.hidden = false;
        } else { box.hidden = true; box.innerHTML = ""; }
      }
    });

    empty.hidden = total > 0;
    more.hidden = total <= shown;
    more.textContent = "Show " + Math.min(PAGE, Math.max(0, total - shown)) + " more of " + total;
    count.textContent = terms.length || cat
      ? total + (total === 1 ? " episode" : " episodes") + " matched" + (visible < total ? " · showing " + visible : "")
      : total + (total === 1 ? " episode" : " episodes");
    clear.hidden = !q.value;
  }

  var t;
  q.addEventListener("input", function () {
    clearTimeout(t);
    t = setTimeout(function () {
      terms = norm(q.value).split(/\s+/).filter(Boolean);
      shown = PAGE;
      apply();
    }, 120);
  });

  clear.addEventListener("click", function () { q.value = ""; terms = []; shown = PAGE; apply(); q.focus(); });

  if (filters) filters.addEventListener("click", function (ev) {
    var b = ev.target.closest(".chip");
    if (!b) return;
    cat = b.getAttribute("data-cat") || "";
    [].forEach.call(filters.children, function (c) { c.classList.toggle("on", c === b); });
    shown = PAGE;
    apply();
  });

  more.addEventListener("click", function () { shown += PAGE; apply(); });

  /* "/" focuses search, the way every archive people already use behaves. */
  document.addEventListener("keydown", function (ev) {
    if (ev.key === "/" && document.activeElement !== q && !/^(INPUT|TEXTAREA)$/.test(document.activeElement.tagName)) {
      ev.preventDefault(); q.focus();
    }
  });

  apply();
})();

/* Table of contents: mark the section you are actually reading. */
(function () {
  "use strict";
  var toc = document.querySelector(".toc");
  if (!toc || !window.IntersectionObserver) return;
  var links = {};
  [].forEach.call(toc.querySelectorAll("a"), function (a) { links[a.getAttribute("href").slice(1)] = a; });
  var heads = Object.keys(links).map(function (id) { return document.getElementById(id); }).filter(Boolean);
  if (!heads.length) return;
  var seen = {};
  var io = new IntersectionObserver(function (entries) {
    entries.forEach(function (en) { seen[en.target.id] = en.isIntersecting; });
    var active = heads.filter(function (h) { return seen[h.id]; })[0] || null;
    for (var id in links) links[id].classList.toggle("on", !!active && id === active.id);
  }, { rootMargin: "0px 0px -70% 0px" });
  heads.forEach(function (h) { io.observe(h); });
})();
